class FactMemory:
    def __init__(self):
        self._data = {}
    def save(self, user, key, value):
        self._data.setdefault(user, {})[key] = value
    def get(self, user, key):
        return self._data.get(user, {}).get(key)
    def forget(self, user, key):
        self._data.get(user, {}).pop(key, None)
    def facts(self, user):
        return dict(self._data.get(user, {}))

import json

def detect_loop(calls, threshold):
    seen = {}
    for i, (tool, args) in enumerate(calls):
        key = (tool, json.dumps(args, sort_keys=True))
        seen[key] = seen.get(key, 0) + 1
        if seen[key] >= threshold:
            return i
    return None
